$root=(Get-Location).Path
$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,8080);$listener.Start();Write-Output "Serving $root at http://localhost:8080/"
$mime=@{'.html'='text/html; charset=utf-8';'.js'='application/javascript; charset=utf-8';'.css'='text/css; charset=utf-8';'.json'='application/json; charset=utf-8';'.png'='image/png';'.jpg'='image/jpeg';'.svg'='image/svg+xml';'.lcc'='application/octet-stream'}
while($true){$c=$listener.AcceptTcpClient();$s=$c.GetStream();$r=[IO.StreamReader]::new($s);$line=$r.ReadLine();$path=[Uri]::UnescapeDataString((($line -split ' ')[1]).TrimStart('/'));if(!$path){$path='index.html'};$f=Join-Path $root $path;if(Test-Path -LiteralPath $f -PathType Leaf){$b=[IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $f).Path);$e=[IO.Path]::GetExtension($f).ToLowerInvariant();$ct=if($mime.ContainsKey($e)){$mime[$e]}else{'application/octet-stream'};$h="HTTP/1.1 200 OK`r`nContent-Type: $ct`r`nContent-Length: $($b.Length)`r`nAccess-Control-Allow-Origin: *`r`nConnection: close`r`n`r`n"}else{$b=[Text.Encoding]::UTF8.GetBytes('Not Found');$h="HTTP/1.1 404 Not Found`r`nContent-Length: $($b.Length)`r`nConnection: close`r`n`r`n"};$hb=[Text.Encoding]::ASCII.GetBytes($h);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length);$s.Close();$c.Close()}
